/* ==================================================================
   스토리 — 100 스테이지 전부에 장면이 붙는다

   노드는 두 종류뿐이다.
     대사   { who, text }
     선택지 { choice: { prompt, options } }

   선택지 option 의 gain 이 아래 세 축에 점수를 쌓고,
   그 총합이 10장 마지막에 고를 수 있는 엔딩을 정한다.

     fusion   융합   — 아르드라와 다시 하나가 되려는 마음
     share    나눔   — 짐을 여럿이 나눠 지려는 마음
     farewell 작별   — 혼자 짊어지고 사라지려는 마음

   [지켜야 할 규칙] 로드맵 13-3 —
   1~6장에는 메타적 균열(WAVE #___, 기록 갱신, 일치율 같은 시스템 텍스트)을
   절대 넣지 않는다. 이 구간은 정서적 복선만 쌓는다. 메타 장치가 10장
   크레딧에서 처음 나와야 충격이 산다. 테스트가 이걸 검사한다.

   [복선 레이어] 여러 갈래를 동시에 깔아 두고 후반에 회수한다.
     ㆍ"반쪽"      정령·프로스트린·벽화가 서로 다른 방식으로 부른다
     ㆍ목걸이      1장부터 걸고 있던 것 → 4장 조각상 → 9장 아르드라
     ㆍ신체 공명   흉통(3장) → 상처 공유(9장)
     ㆍ숫자 열     섬의 사물이 자꾸 열 개씩 세어진다
     ㆍ시간        섬에서만 나이를 먹지 않는 것들
     ㆍ그림자      적처럼 굴지만 매번 결정적일 때 물러선다
     ㆍ카이든      배신자로 보이는 행동에 늘 다른 설명이 가능하다
     ㆍ루나의 기록 손에 쥔 것을 자꾸 감춘다 → 7장에 정체가 드러난다
     ㆍ비            섬에 비가 오는 날은 반드시 뭔가가 시작된다
     ㆍ이름          누구도 주인공의 이름을 부르지 않는다
   ================================================================== */

export const AXES = ['fusion', 'share', 'farewell']
export const freshFlags = () => ({ fusion: 0, share: 0, farewell: 0 })

const L = (who, text) => ({ who, text })
const C = (prompt, options) => ({ choice: { prompt, options } })

