/* 본 장면 모음 — 확장 블록이 이 앞에 붙는다 */
const BASE = {
  ...CH1, ...CH2, ...CH3, ...CH4, ...CH5, ...CH6, ...CH7, ...CH8, ...CH9, ...CH10,
  ...FILL1, ...FILL2, ...FILL3, ...FILL4, ...FILL5,
  ...FILL6, ...FILL7, ...FILL8, ...FILL9, ...FILL10,
}

/* 확장 블록 — 스테이지마다 앞부분을 덧댄다.
   본 장면이 그 스테이지의 정점이므로 확장은 반드시 앞에 놓는다.
   뒤에 붙이면 절정 뒤에 잡담이 이어져 맥이 풀린다. */
const EXPAND = { ...X1, ...X2, ...X3, ...X4, ...X5, ...X6, ...X7, ...X8, ...X9, ...X10 }


/* 여담까지 얹고도 한두 줄이 모자란 스테이지를 채우는 짧은 마무리.
   여담 풀이 그 장에서 이미 다 쓰였을 때만 쓰인다. */
