const ASIDES = { ...ASIDE, ...ASIDE_B, ...ASIDE_C }

/* 확장까지 붙이고도 20줄이 안 되는 스테이지에 여담을 하나씩 더 얹는다.
   한 장 안에서 같은 여담이 두 번 쓰이면 금방 들키므로, 그 장에서
   모자란 스테이지를 순서대로 세어 i번째에 i번째 여담을 준다. */
const MIN_LINES = 20
const linesOf = (sc) => sc.reduce((a, n) => a + (n.choice
  ? n.choice.options.reduce((b, o) => b + (o.reply?.length || 0), 0)
  : 1), 0)

function buildScripts() {
  const merged = Object.fromEntries(
    Object.entries(BASE).map(([id, sc]) => [id, EXPAND[id] ? [...EXPAND[id], ...sc] : sc]),
  )
  const used = {}
  for (const id of Object.keys(merged)) {
    if (linesOf(merged[id]) >= MIN_LINES) continue
    const ch = Number(id.split('-')[0])
    const pool = ASIDES[ch]
    if (!pool) continue
    const i = used[ch] = (used[ch] ?? -1) + 1
    const aside = pool[i]
    if (aside) merged[id] = [...aside, ...merged[id]]
  }
  /* 그래도 모자라면 짧은 마무리를 하나 더 얹는다 */
  let t = 0
  for (const id of Object.keys(merged)) {
    if (linesOf(merged[id]) >= MIN_LINES) continue
    merged[id] = [...merged[id], ...TAIL[t++ % TAIL.length]]
  }
  return merged
}

export const SCRIPTS = buildScripts()

/* 10장 마지막 스테이지를 깨면 엔딩 선택이 뜬다 */
export const FINAL_STAGE_ID = '10-30'

